<?php require_once __DIR__.'/../includes/functions.php'; $username=(string)($_GET['username']??'');$resource=(string)($_GET['resource']??'');$u=get_user($username);if(!$u)json_response(['error'=>'Usuário não encontrado'],404);$c=user_config($u);switch($resource){case 'config':$c['Update']=update_resource($username,'config');json_response($c);case 'appupdate':json_response(['Version'=>(string)$c['AppVersion'],'Update'=>$c['UpdateApk']??'','VersionName'=>$c['VersionName']??(string)$c['AppVersion'],'UpdateApk'=>$c['UpdateApk']??'','Actualization'=>$c['Actualization']??'false']);case 'sms':json_response($c['Sms']);case 'theme':json_response($c['Theme']);default:json_response(['error'=>'Recurso inválido'],404);}
